import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.DXf0zkj5.js";const m=JSON.parse('{"title":"Technical Glossary & Concepts Reference","description":"","frontmatter":{},"headers":[],"relativePath":"11-glossary.md","filePath":"11-glossary.md"}'),i={name:"11-glossary.md"};function o(s,e,c,l,d,g){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="technical-glossary-concepts-reference" tabindex="-1">Technical Glossary &amp; Concepts Reference <a class="header-anchor" href="#technical-glossary-concepts-reference" aria-label="Permalink to &quot;Technical Glossary &amp; Concepts Reference&quot;">​</a></h1><p>A comprehensive dictionary of systems engineering, HTTP caching, and networking terminology used in <code>17-cdn-caching-proxy</code>.</p><hr><h2 id="caching-networking-terms" tabindex="-1">Caching &amp; Networking Terms <a class="header-anchor" href="#caching-networking-terms" aria-label="Permalink to &quot;Caching &amp; Networking Terms&quot;">​</a></h2><ul><li><strong>RFC 9111</strong>: The modern IETF standard specification governing HTTP Caching semantics, replacing RFC 7234.</li><li><strong>Request Coalescing (Single-Flight)</strong>: An architectural pattern that intercepts multiple concurrent requests for the same uncached resource and collapses them into a single upstream request, protecting origins from thundering herd stampedes.</li><li><strong>Surrogate-Key (Cache-Tag)</strong>: A response header containing space-separated identifiers that tag cached representations, enabling bulk invalidation of related resources in O(1) time.</li><li><strong>Stale-While-Revalidate (RFC 5861)</strong>: A Cache-Control directive instructing the proxy to serve an expired cached entry immediately to the client while asynchronously dispatching a background request to fetch fresh content.</li><li><strong>Stale-If-Error (RFC 5861)</strong>: A Cache-Control directive allowing the proxy to serve an expired cached response if the upstream origin returns a 5xx error or network timeout.</li><li><strong>Canonical Cache Key</strong>: A normalized SHA-256 hash derived from the request URL, query parameters (sorted deterministically), and secondary keys from <code>Vary</code> headers.</li><li><strong>Segmented LRU (SLRU)</strong>: An eviction algorithm that divides cache space into probationary and protected segments, requiring an asset to be accessed at least twice before entering the protected tier.</li><li><strong>Ketama Consistent Hashing</strong>: A deterministic hashing algorithm that maps cache keys and server nodes onto a 32-bit ring with virtual nodes, minimizing key migration during node additions or removals.</li><li><strong>Zero-Copy Stream Piping</strong>: Transferring raw byte chunks from an ingress socket to an egress socket without deserializing the payload into intermediate application memory.</li><li><strong>Content Negotiation</strong>: The HTTP mechanism (<code>Accept-Encoding</code> vs <code>Content-Encoding</code>) allowing clients and proxies to negotiate optimal data formats such as Brotli or Gzip.</li></ul>',5)])])}const p=t(i,[["render",o]]);export{m as __pageData,p as default};
